import{_ as i,a0 as l,w as g,s as m,ao as o,I as e,x as p,a1 as s,A as r}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const I=JSON.parse('{"title":"使用條塊化I/O管理多個LVM磁盤（第五部分） | LCTT x X-CMD","titleTemplate":false,"description":"使用條塊化I/O管理多個LVM磁盤（第五部分） | LCTT (201412) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"使用條塊化I/O管理多個LVM磁盤（第五部分） | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"使用條塊化I/O管理多個LVM磁盤（第五部分） | LCTT (201412) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201412/20141013 Manage Multiple Logical Volume Management Disks using Striping I O--Part V","title":"使用條塊化I/O管理多個LVM磁盤（第五部分）","tag":"201412","desc":""},"relativePath":"201412/20141013 Manage Multiple Logical Volume Management Disks using Striping I O--Part V.md","filePath":"[post].md"}'),a={name:"201412/20141013 Manage Multiple Logical Volume Management Disks using Striping I O--Part V.md"};function d(u,t,w,v,V,L){const n=l("Link");return g(),m("div",null,[t[30]||(t[30]=o(`<h1 id="使用條塊化i-o管理多個lvm磁盤-第五部分" tabindex="-1">使用條塊化I/O管理多個LVM磁盤（第五部分） <a class="header-anchor" href="#使用條塊化i-o管理多個lvm磁盤-第五部分" aria-label="Permalink to “使用條塊化I/O管理多個LVM磁盤（第五部分）”">​</a></h1><p>在本文中，我們將瞭解邏輯卷是如何通過條塊化I/O來寫入數據到磁盤的。邏輯卷管理的酷炫特性之一，就是它能通過條塊化I/O跨多個磁盤寫入數據。</p><h3 id="lvm條塊化是什麼" tabindex="-1">LVM條塊化是什麼？ <a class="header-anchor" href="#lvm條塊化是什麼" aria-label="Permalink to “LVM條塊化是什麼？”">​</a></h3><p><strong>LVM條塊化</strong>是LVM功能之一，該技術會跨多個磁盤寫入數據，而不是對單一物理卷持續寫入。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/LVM-Striping.jpeg" alt="Manage LVM Disks Using Striping I/O"></p><p><em>使用條塊化I/O管理LVM磁盤</em></p><h4 id="條塊化特性" tabindex="-1">條塊化特性 <a class="header-anchor" href="#條塊化特性" aria-label="Permalink to “條塊化特性”">​</a></h4><ul><li>它會改善磁盤性能。</li><li>避免對單一磁盤的不斷的大量寫入。</li><li>使用對多個磁盤的條塊化寫入，可以減少磁盤填滿的幾率。</li></ul><p>在邏輯卷管理中，如果我們需要創建一個邏輯卷，擴展的卷會完全映射到卷組和物理卷。在此種情形中，如果其中一個<strong>PV</strong>（物理卷）被填滿，我們需要從其它物理卷中添加更多擴展。這樣，添加更多擴展到PV中後，我們可以指定邏輯卷使用特定的物理卷寫入I/O。</p><p>假設我們有<strong>四個磁盤</strong>驅動器，分別指向了四個物理卷，如果各個物理卷總計可以達到<strong>100 I/O</strong>，我們卷組就可以獲得<strong>400 I/O</strong>。</p><p>如果我們不使用<strong>條塊化方法</strong>，文件系統將橫跨基礎物理卷寫入。例如，寫入一些數據到物理卷達到100 I/O，這些數據只會寫入到第一個PV（<strong>sdb1</strong>）。如果我們在寫入時使用條塊化選項創建邏輯卷，它會分割100 I/O分別寫入到四個驅動器中，這就是説每個驅動器中都會接收到25 I/O。</p><p>這會在循環過程中完成。如果這些邏輯卷其中任何一個需要擴展，在這種情形下，我們不能添加1個或2個PV，必須添加所有4個pv來擴展邏輯卷大小。這是條塊化特性的缺點之一，從中我們可以知道，在創建邏輯卷時，我們需要為所有邏輯卷分配相同的條塊大小。</p><p>邏輯卷管理有着這些特性，它使我們能夠同時在多個pv中條塊化數據。如果你對邏輯卷熟悉，你可以去設置邏輯卷條塊化。反之，你則必須瞭解邏輯卷管理的基礎知識了，請閲讀更基礎的文章來了解邏輯卷管理。</p><h4 id="我的服務器設置" tabindex="-1">我的服務器設置 <a class="header-anchor" href="#我的服務器設置" aria-label="Permalink to “我的服務器設置”">​</a></h4><p>這裏，我使用<strong>CentOS6.5</strong>用作練習。下面這些步驟也適用於RHEL、Oracle Linux以及大多數發行版。</p><pre><code>操作系統：	   CentOS 6.5
IP地址：		192.168.0.222
主機名：	    tecmint.storage.com
</code></pre><h3 id="條塊化i-o的邏輯卷管理" tabindex="-1">條塊化I/O的邏輯卷管理 <a class="header-anchor" href="#條塊化i-o的邏輯卷管理" aria-label="Permalink to “條塊化I/O的邏輯卷管理”">​</a></h3><p>出於演示目的，我已經準備了4個硬盤驅動器，每個驅動器1GB大小。讓我用下面的‘<strong>fdisk</strong>’命令來列給你看看吧。</p><pre><code># fdisk -l | grep sd
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/List-Hard-Drives.png" alt="List Hard Drives"></p><p><em>列出硬盤驅動器</em></p>`,21)),e("p",null,[t[1]||(t[1]=p("現在，我們必須為這4個硬盤驅動器",-1)),t[2]||(t[2]=e("strong",null,"sdb",-1)),t[3]||(t[3]=p("，",-1)),t[4]||(t[4]=e("strong",null,"sdc",-1)),t[5]||(t[5]=p("，",-1)),t[6]||(t[6]=e("strong",null,"sdd",-1)),t[7]||(t[7]=p("和",-1)),t[8]||(t[8]=e("strong",null,"sde",-1)),t[9]||(t[9]=p("創建分區，我們將用‘",-1)),t[10]||(t[10]=e("strong",null,"fdisk",-1)),t[11]||(t[11]=p("’命令來完成該工作。要創建分區，請遵從本文",-1)),e("strong",null,[s(n,{href:"http://linux.cn/article-3965-1.html"},{default:r(()=>[...t[0]||(t[0]=[p("第一部分",-1)])]),_:1})]),t[12]||(t[12]=p("中",-1)),t[13]||(t[13]=e("strong",null,"步驟#4",-1)),t[14]||(t[14]=p("的説明，並在創建分區時確保你已將類型修改為",-1)),t[15]||(t[15]=e("strong",null,"LVM（8e）",-1)),t[16]||(t[16]=p("。",-1))]),t[31]||(t[31]=o(`<pre><code># pvcreate /dev/sd[b-e]1 -v
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Create-Physical-Volumes-in-LVM.png" alt="Create Physical Volumes in LVM"></p><p><em>在LVM中創建物理卷</em></p><p>PV創建完成後，你可以使用‘<strong>pvs</strong>’命令將它們列出來。</p><pre><code># pvs
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Verify-Physical-Volumes.png" alt="Verify Physical Volumes"></p><p><em>驗證物理卷</em></p><p>現在，我們需要使用這4個物理捲來定義卷組。這裏，我定義了一個物理擴展大小（PE）為<strong>16MB</strong>，名為<strong>vg_strip</strong>的卷組。</p><pre><code># vgcreate -s 16M vg_strip /dev/sd[b-e]1 -v
</code></pre><p>上面命令中選項的説明：</p><ul><li><strong>[b-e]1</strong> – 定義硬盤驅動器名稱，如sdb1，sdc1，sdd1，sde1。</li><li><strong>-s</strong> – 定義物理擴展大小。</li><li><strong>-v</strong> – 詳情。</li></ul><p>接下來，驗證新創建的卷組：</p><pre><code># vgs vg_strip
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Verify-Volume-Group.png" alt="Verify Volume Group"></p><p><em>驗證卷組</em></p><p>要獲取VG更詳細的信息，可以在<strong>vgdisplay</strong>命令中使用‘-v’選項，它將給出<strong>vg_strip</strong>卷組中所使用的全部物理卷的詳細情況。</p><pre><code># vgdisplay vg_strip -v
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Volume-Group-Information.png" alt="Volume Group Information"></p><p><em>卷組信息</em></p><p>回到我們的話題，現在在創建邏輯卷時，我們需要定義條塊化值，就是數據需要如何使用條塊化方法來寫入到我們的邏輯卷中。</p><p>這裏，我創建了一個名為<strong>lv_tecmint-strp1</strong>，大小為<strong>900MB</strong>的邏輯卷，它需要放到<strong>vg_strip</strong>卷組中。我定義了4個條塊，就是説數據在寫入到我的邏輯卷時，需要條塊化分散到4個PV中。</p><pre><code># lvcreate -L 900M -n lv_tecmint_strp1 -i4 vg_strip
</code></pre><ul><li><strong>-L</strong> –邏輯卷大小</li><li><strong>-n</strong> –邏輯卷名稱</li><li><strong>-i</strong> –條塊化</li></ul><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Create-Logical-Volumes.png" alt="Create Logical Volumes"></p><p><em>創建邏輯卷</em></p><p>在上面的圖片中，我們可以看到條塊尺寸的默認大小為<strong>64 KB</strong>，如果我們需要自定義條塊值，我們可以使用<strong>-I</strong>（大寫I）。要確認邏輯卷已經是否已經創建，請使用以下命令。</p><pre><code># lvdisplay vg_strip/lv_tecmint_strp1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Confirm-Logical-Volumes.png" alt="Confirm Logical Volumes"></p><p><em>確認邏輯卷</em></p><p>現在，接下來的問題是，我們怎樣才能知道條塊被寫入到了4個驅動器。這裏，我們可以使用‘<strong>lvdisplay</strong>’和<strong>-m</strong>（顯示邏輯卷映射）命令來驗證。</p><pre><code># lvdisplay vg_strip/lv_tecmint_strp1 -m
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Check-Logical-Volumes.png" alt="Check Logical Volumes"></p><p><em>檢查邏輯卷</em></p><p>要創建自定義的條塊尺寸，我們需要用我們自定義的條塊大小<strong>256KB</strong>來創建一個<strong>1GB</strong>大小的邏輯卷。現在，我打算將條塊分佈到3個PV上。這裏，我們可以定義我們想要哪些pv條塊化。</p><pre><code># lvcreate -L 1G -i3 -I 256 -n lv_tecmint_strp2 vg_strip /dev/sdb1 /dev/sdc1 /dev/sdd1
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Define-Stripe-Size.png" alt="Define Stripe Size"></p><p><em>定義條塊大小</em></p><p>接下來，檢查條塊大小和條塊化的卷。</p><pre><code># lvdisplay vg_strip/lv_tecmint_strp2 -m
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Check-Stripe-Size.png" alt="Check Stripe Size"></p><p><em>檢查條塊大小</em></p><p>是時候使用設備映射了，我們使用‘<strong>dmsetup</strong>’命令來完成這項工作。它是一個低級別的邏輯卷管理工具，它用於管理使用了設備映射驅動的邏輯設備。</p><pre><code># dmsetup deps /dev/vg_strip/lv_tecmint_strp[1-2]
</code></pre><p><img src="http://www.tecmint.com/wp-content/uploads/2014/09/Device-Mapper.png" alt="Device Mapper"></p><p><em>設備映射</em></p><p>這裏，我們可以看到strp1依賴於4個驅動器，strp2依賴於3個設備。</p><p>希望你已經明白，我們怎樣能讓邏輯卷條塊化來寫入數據。對於此項設置，必須掌握邏輯卷管理基礎知識。</p><p>在我的下一篇文章中，我將給大家展示怎樣在邏輯卷管理中遷移數據。到那時，請靜候更新。同時，別忘了對本文提出有價值的建議。</p><hr>`,49)),e("p",null,[t[18]||(t[18]=p("via: ",-1)),s(n,{href:"http://www.tecmint.com/manage-multiple-lvm-disks-using-striping-io/"},{default:r(()=>[...t[17]||(t[17]=[p("http://www.tecmint.com/manage-multiple-lvm-disks-using-striping-io/",-1)])]),_:1})]),e("p",null,[t[22]||(t[22]=p("作者：",-1)),s(n,{href:"http://www.tecmint.com/author/babinlonston/"},{default:r(()=>[...t[19]||(t[19]=[p("Babin Lonston",-1)])]),_:1}),t[23]||(t[23]=p(" 譯者：",-1)),s(n,{href:"https://github.com/GOLinux"},{default:r(()=>[...t[20]||(t[20]=[p("GOLinux",-1)])]),_:1}),t[24]||(t[24]=p(" 校對：",-1)),s(n,{href:"https://github.com/wxy"},{default:r(()=>[...t[21]||(t[21]=[p("wxy",-1)])]),_:1})]),e("p",null,[t[27]||(t[27]=p("本文由 ",-1)),s(n,{href:"https://github.com/LCTT/TranslateProject"},{default:r(()=>[...t[25]||(t[25]=[p("LCTT",-1)])]),_:1}),t[28]||(t[28]=p(" 原創翻譯，",-1)),s(n,{href:"http://linux.cn/"},{default:r(()=>[...t[26]||(t[26]=[p("Linux中國",-1)])]),_:1}),t[29]||(t[29]=p(" 榮譽推出",-1))])])}const c=i(a,[["render",d]]);export{I as __pageData,c as default};
